diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..fb4e2fe 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,56 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const lineasDemo = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006-a: descuento global en porcentaje antes del IVA informado", () => {
+  assert.deepEqual(calcularFactura(lineasDemo, { descuentoGlobal: 10 }), {
+    subtotalCentavos: 11050,
+    descuentoCentavos: 1105,
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("RF-006-b: sin descuento o con 0 el resultado es el de RF-002", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(lineasDemo), esperado);
+  assert.deepEqual(calcularFactura(lineasDemo, {}), esperado);
+  assert.deepEqual(calcularFactura(lineasDemo, { descuentoGlobal: 0 }), esperado);
+});
+
+test("RF-006-c: descuento de 100 % deja total 0", () => {
+  const f = calcularFactura(lineasDemo, { descuentoGlobal: 100 });
+  assert.equal(f.totalCentavos, 0);
+  assert.equal(f.ivaCentavos, 0);
+  assert.equal(f.netoCentavos, 0);
+});
+
+test("RF-006-d: descuento global inválido se rechaza", () => {
+  for (const malo of [-1, 101, "10", Number.NaN, Infinity, null]) {
+    assert.throws(() => calcularFactura(lineasDemo, { descuentoGlobal: malo }), RangeError);
+  }
+});
+
+test("RF-006-e: el descuento se redondea al centavo entero", () => {
+  const f = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 3333 }], { descuentoGlobal: 10 });
+  assert.equal(f.descuentoCentavos, 333);
+  assert.equal(f.totalCentavos, 3000);
+  assert.ok(Number.isInteger(f.ivaCentavos) && Number.isInteger(f.netoCentavos));
+});
+
+test("RF-006-f: la factura emitida con descuento global queda congelada y lo conserva", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: lineasDemo, descuentoGlobal: 10 });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.descuentoGlobal, 10);
+  assert.equal(f.totalCentavos, 9945);
+  assert.equal(f.estado, "emitida");
+});
